// Univariate autocorrelation, partial autocorrelation and cross-correlation.
import { qnorm } from "../distributions/normal.js";
// Generated by `node scripts/option-keys.mjs --write` from the option types; do not edit (begin)
import { checkOptions } from "../internal/checkOptions.js";
const ACF_KEYS = ["type", "lagMax", "demean", "naAction", "ci"] as const;
const PACF_KEYS = ["lagMax", "naAction"] as const;
const CCF_KEYS = ["type", "lagMax", "demean", "naAction", "ci"] as const;
// Generated by `node scripts/option-keys.mjs --write` (end)

/** @category Time series */
export type AcfType = "correlation" | "covariance" | "partial";
/** @category Time series */
export type AcfNaAction = "fail" | "pass";
/** @category Time series */
export interface AcfOptions {
  type?: AcfType;
  lagMax?: number;
  demean?: boolean;
  naAction?: AcfNaAction;
  ci?: number;
}
/** @category Time series */
export interface PacfOptions { lagMax?: number; naAction?: AcfNaAction; }
/** @category Time series */
export interface CcfOptions {
  type?: "correlation" | "covariance";
  lagMax?: number;
  demean?: boolean;
  naAction?: AcfNaAction;
  ci?: number;
}
/** @category Time series */
export interface AcfResult {
  lag: number[];
  acf: number[];
  type: AcfType;
  nUsed: number;
  clim: number;
}

function series(input: readonly number[] | readonly (readonly number[])[]): number[] {
  if (!Array.isArray(input)) throw new TypeError("'x' must be numeric");
  if (input.length === 0) throw new RangeError("'ts' object must have one or more observations");
  if (Array.isArray(input[0])) {
    const matrix = input as readonly (readonly number[])[];
    if (matrix.some((row) => !Array.isArray(row) || row.length !== 1)) {
      throw new RangeError("multivariate time series are not supported");
    }
    return matrix.map((row) => Number(row[0]));
  }
  return (input as readonly number[]).map(Number);
}
function validate(values: readonly number[], action: AcfNaAction): void {
  if (action !== "fail" && action !== "pass") throw new RangeError("'naAction' must be 'fail' or 'pass'");
  if (action === "fail" && values.some(Number.isNaN)) throw new RangeError("missing values in object");
}
function mean(values: readonly number[]): number {
  let sum = 0, count = 0;
  for (const v of values) if (!Number.isNaN(v)) { sum += v; count++; }
  return count ? sum / count : NaN;
}
function maxLag(n: number, value: number | undefined, minimum: number): number {
  const requested = value === undefined ? Math.floor(10 * Math.log10(n)) : value;
  if (!Number.isFinite(requested) || requested < minimum) throw new RangeError(minimum === 1 ? "'lag.max' must be at least 1" : "'lag.max' must be at least 0");
  return Math.min(Math.floor(requested), n - 1);
}
function covariance(x: readonly number[], y: readonly number[], lag: number, mx: number, my: number, demean: boolean, pass: boolean): number {
  const n = x.length;
  let sum = 0, count = 0;
  const start = lag >= 0 ? 0 : -lag;
  const end = lag >= 0 ? n - lag : n;
  for (let t = start; t < end; t++) {
    const a = x[t + lag]!, b = y[t]!;
    if (Number.isNaN(a) || Number.isNaN(b)) continue;
    sum += (demean ? a - mx : a) * (demean ? b - my : b);
    count++;
  }
  const divisor = pass ? count + Math.abs(lag) : n;
  return divisor ? sum / divisor : NaN;
}
function partial(correlations: readonly number[]): number[] {
  const out: number[] = [];
  const previous: number[] = [];
  for (let k = 1; k < correlations.length; k++) {
    let numerator = correlations[k]!;
    let denominator = 1;
    for (let j = 1; j < k; j++) {
      numerator -= previous[j - 1]! * correlations[k - j]!;
      denominator -= previous[j - 1]! * correlations[j]!;
    }
    const phi = numerator / denominator;
    const next = new Array<number>(k);
    for (let j = 1; j < k; j++) next[j - 1] = previous[j - 1]! - phi * previous[k - j - 1]!;
    next[k - 1] = phi;
    previous.splice(0, previous.length, ...next);
    out.push(phi);
  }
  return out;
}
function build(x: number[], y: number[], options: { type: "correlation" | "covariance" | "partial"; lagMax?: number; demean?: boolean; naAction?: AcfNaAction; ci?: number }, isCross: boolean): AcfResult {
  const action = options.naAction ?? "fail";
  validate(x, action);
  validate(y, action);
  if (x.length !== y.length) throw new RangeError("time series must have the same length");
  const n = x.length, demean = options.demean ?? true;
  const mx = mean(x), my = mean(y);
  const limit = maxLag(n, options.lagMax, isCross || options.type !== "partial" ? 0 : 1);
  const covs: number[] = [];
  const first = covariance(x, y, 0, mx, my, demean, action === "pass");
  const second = isCross ? covariance(y, y, 0, my, my, demean, action === "pass") : first;
  for (let k = 0; k <= limit; k++) covs.push(covariance(x, y, k, mx, my, demean, action === "pass"));
  let values: number[];
  if (options.type === "covariance") values = covs;
  else {
    const scale = isCross ? Math.sqrt(first * second) : first;
    const corr = covs.map((v) => v / scale);
    values = options.type === "partial" ? partial(corr) : corr;
  }
  const lag = options.type === "partial" ? Array.from({ length: limit }, (_, i) => i + 1) : Array.from({ length: limit + 1 }, (_, i) => i);
  const ci = options.ci ?? 0.95;
  if (!Number.isFinite(ci) || ci <= 0 || ci >= 1) throw new RangeError("'ci' must be between 0 and 1");
  return { lag, acf: values, type: options.type, nUsed: n, clim: qnorm((1 + ci) / 2) / Math.sqrt(n) };
}

/**
 * Autocorrelation, autocovariance or partial autocorrelation of a univariate series.
 * @category Time series
 */
export function acf(input: readonly number[] | readonly (readonly number[])[], options: AcfOptions = {}): AcfResult {
  checkOptions(options, ACF_KEYS, "acf");
  const x = series(input);
  const type = options.type ?? "correlation";
  if (type !== "correlation" && type !== "covariance" && type !== "partial") throw new RangeError("'type' must be 'correlation', 'covariance' or 'partial'");
  return build(x, x, { ...options, type }, false);
}

/**
 * Partial autocorrelation of a univariate series, computed by the Durbin–Levinson recursion.
 * @category Time series
 */
export function pacf(input: readonly number[] | readonly (readonly number[])[], options: PacfOptions = {}): AcfResult {
  checkOptions(options, PACF_KEYS, "pacf");
  return acf(input, { ...options, type: "partial" });
}

/**
 * Cross-correlation or cross-covariance of two equal-length series. Lag k pairs x[t+k] with y[t].
 * @category Time series
 */
export function ccf(xInput: readonly number[] | readonly (readonly number[])[], yInput: readonly number[] | readonly (readonly number[])[], options: CcfOptions = {}): AcfResult {
  checkOptions(options, CCF_KEYS, "ccf");
  const x = series(xInput), y = series(yInput);
  const type = options.type ?? "correlation";
  if (type !== "correlation" && type !== "covariance") throw new RangeError("'type' must be 'correlation' or 'covariance'");
  const action = options.naAction ?? "fail";
  validate(x, action); validate(y, action);
  if (x.length !== y.length) throw new RangeError("time series must have the same length");
  const n = x.length, limit = maxLag(n, options.lagMax, 0);
  const demean = options.demean ?? true, mx = mean(x), my = mean(y);
  const xx = covariance(x, x, 0, mx, mx, demean, action === "pass");
  const yy = covariance(y, y, 0, my, my, demean, action === "pass");
  const divisor = type === "correlation" ? Math.sqrt(xx * yy) : 1;
  const lag: number[] = [], values: number[] = [];
  for (let k = -limit; k <= limit; k++) {
    lag.push(k);
    const v = covariance(x, y, k, mx, my, demean, action === "pass");
    values.push(type === "correlation" ? v / divisor : v);
  }
  const ci = options.ci ?? 0.95;
  if (!Number.isFinite(ci) || ci <= 0 || ci >= 1) throw new RangeError("'ci' must be between 0 and 1");
  return { lag, acf: values, type, nUsed: n, clim: qnorm((1 + ci) / 2) / Math.sqrt(n) };
}
